import sys
bad = 0
hunk = False
for line in open(sys.argv[1], 'rb'):
    if line.startswith(b'diff --git '):
        hunk = False
    elif line.startswith(b'@@'):
        hunk = True
    elif hunk and line.startswith(b'+'):
        text = line[1:].rstrip(b'\r\n')
        if text != text.rstrip() or text.startswith((b'<<<<<<< ', b'>>>>>>> ')):
            bad += 1
if bad:
    print(f'{bad} added line(s) with trailing whitespace or conflict markers')
sys.exit(1 if bad else 0)
